h:65839893.patch:
@@ -73,12 +76,22 @@ if [ "$cmd" = dispatch ]; then
   exit "$rc"
 fi

-delivery=$3 actor=$4 device=$5 digest=$6 head=$7 base=$8 policy=$9 revision=${10} seen=${11} supersede=${12}
+delivery=$3 actor=$4 device=$5 digest=$6 head=$7 base=$8 policy=$9 revision=${10} seen=${11} supersede=${12} lease=${13:-}
+[ -z "$lease" ] || [ "$delivery" = force-push ] || fail "a lease is for force-push only"
 case "$delivery" in
   none) actions=() ;;
   push) actions=(--action push) ;;
   pr) actions=(--action push --action pr) ;;
-  *) fail "'$delivery' is not a delivery choice: none, push or pr" ;;
+  force-push)
+    # Only the remote head this packet recorded on a chain break, and only while
+    # it is still this ticket's newest packet: kk-approval decides the rest.
+    facts=$(kk-approval status "$ticket" --output json "${ws[@]+"${ws[@]}"}") || exit $?
+    jq -e --arg p "$pid" --arg l "$lease" --arg h "$head" \
+       '.packet == $p and .packet_facts.chain_break != null and .packet_facts.remote_head == $l and $l != $h' \
+       <<< "$facts" >/dev/null \
+      || fail "force-push needs a chain-break packet and, as its lease, the remote head that packet recorded"
+    actions=(--action force-push --lease "$lease") ;;
+  *) fail "'$delivery' is not a delivery choice: none, push, pr or force-push" ;;
 esac
 printf '%s' "$device" | grep -qE '^[a-z0-9][a-z0-9-]{0,62}$' || fail "'$device' is not a device name"
 printf '%s' "$digest" | grep -qE '^sha256:[0-9a-f]{64}$' || fail "'$digest' is not a packet digest"

